"""Count a glibc C file's definitions and nonblank, noncomment lines (GNU style)."""
import re, sys

def strip_comments(text):
    out, i, n = [], 0, len(text)
    while i < n:
        if text.startswith('/*', i):
            j = text.find('*/', i + 2); j = n if j < 0 else j + 2
            out.append('\n' * text.count('\n', i, j)); i = j
        elif text.startswith('//', i):
            j = text.find('\n', i); j = n if j < 0 else j
            i = j
        elif text[i] == '"':
            j = i + 1
            while j < n and text[j] != '"':
                j += 2 if text[j] == '\\' else 1
            out.append(text[i:j + 1]); i = j + 1
        else:
            out.append(text[i]); i += 1
    return ''.join(out)

for path in sys.argv[1:]:
    src = strip_comments(open(path, encoding='utf-8', errors='replace').read())
    lines = src.split('\n')
    loc = sum(1 for l in lines if l.strip() and not l.lstrip().startswith('#'))
    funcs = []
    for k, l in enumerate(lines):
        if l.startswith('{'):
            for b in range(k - 1, max(k - 12, -1), -1):
                m = re.match(r'^(?:[\w\s\*]*?[\s\*])?(\w+)\s*\(', lines[b])
                if m and not lines[b].startswith((' ', '\t', '#')):
                    funcs.append(m.group(1)); break
    structs = re.findall(r'^\s*(?:typedef\s+)?struct\s+(\w+)\s*\n?\s*\{', src, re.M)
    globs = [m.group(1) for m in re.finditer(
        r'^(?!typedef|extern|static\s+inline|#|struct\s+\w+\s*$)(?:static\s+)?(?:const\s+)?[\w\s\*]+?[\s\*](\w+)(?:\s*\[[^\]]*\])?\s*(?:=[^;{]*)?;', src, re.M)]
    print(path, 'loc', loc, 'functions', len(funcs), 'structs', structs, 'globals', globs)
    print('  ', funcs)
